const horariosDeAgente = `-- name: HorariosDeAgente :many
SELECT h.id, h.empresa_id, h.nombre, h.zona, h.franjas, h.feriados, h.activo, h.version, h.created_at, h.updated_at FROM mensajeria.horarios h
WHERE h.activo AND h.id IN (
    SELECT co.horario_id FROM mensajeria.colas co
    WHERE co.activa AND co.horario_id IS NOT NULL AND coalesce(co.empresa_id, 0) = $1::bigint
      AND (EXISTS (SELECT 1 FROM mensajeria.cola_miembros m WHERE m.cola_id = co.id AND m.usuario_id = $2::bigint)
           OR EXISTS (SELECT 1 FROM mensajeria.cola_supervisores s WHERE s.cola_id = co.id AND s.usuario_id = $2::bigint))
    UNION
    SELECT ca.horario_id FROM mensajeria.canales ca JOIN mensajeria.colas co ON co.id = ca.cola_id
    WHERE ca.activo AND co.activa AND co.horario_id IS NULL AND ca.horario_id IS NOT NULL AND coalesce(co.empresa_id, 0) = $1::bigint
      AND (EXISTS (SELECT 1 FROM mensajeria.cola_miembros m WHERE m.cola_id = co.id AND m.usuario_id = $2::bigint)
           OR EXISTS (SELECT 1 FROM mensajeria.cola_supervisores s WHERE s.cola_id = co.id AND s.usuario_id = $2::bigint)))
ORDER BY h.id
`

